package com.franco.desco.adapter.out.sqlserver.cultivation;
import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.cultivation.CultivationCommands.*;import com.franco.desco.application.cultivation.port.out.CultivationPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.cultivation.CultivationModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class CultivationSqlServerAdapter implements CultivationPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory f;private final SimpleJdbcCall list,get,createPlot,updatePlot,createCrop,updateCrop,finishCrop;public CultivationSqlServerAdapter(SqlServerPaFactory x,SqlServerPaExecutor e,PaPayloadFactory f){this.e=e;this.f=f;list=x.callWithResultSets("prod","PA_ParcelaCultivo_Sel_Listado","items");get=x.callWithResultSets("prod","PA_ParcelaCultivo_Sel_DetalleExpediente","parcela","cultivos","censos","evaluaciones","archivos");createPlot=x.call("prod","PA_Parcela_Ins_Registro");updatePlot=x.call("prod","PA_Parcela_Upd_Registro");createCrop=x.call("prod","PA_Cultivo_Ins_Registro");updateCrop=x.call("prod","PA_Cultivo_Upd_Registro");finishCrop=x.call("prod","PA_Cultivo_Upd_Finalizar");}
 public PersistenceResult<PageResult<CultivationModels.Summary>>list(ListCultivations c,SessionIdentity i,RequestMetadata m){int p=c.page().pagina(),s=c.page().tamanio();Filter z=c.page().filtros();var filters=map("predioId",z==null?null:z.predioId(),"socioId",z==null?null:z.socioId(),"variedadPaltaId",z==null?null:z.variedadPaltaId(),"situacionCultivo",z==null?null:z.situacionCultivo(),"buscar",z==null?null:z.buscar(),"pagina",p,"tamanoPagina",s);var rs=e.executeJsonMultiResult(list,f.forQuery(i,m,Map.of("filtros",filters)));return PaAdapterSupport.page(rs.raw(),rs.rows("items"),p,s,this::summary,"No se pudieron consultar las parcelas y cultivos.");}
 public PersistenceResult<CultivationModels.Detail>get(GetCultivation c,SessionIdentity i,RequestMetadata m){var filters=map("parcelaId",c.parcelaId(),"parcelaCultivoId",c.parcelaCultivoId());var rs=e.executeJsonMultiResult(get,f.forQuery(i,m,Map.of("filtros",filters)));if(!PaAdapterSupport.success(rs.raw()))return PersistenceResult.error(PaAdapterSupport.message(rs.raw(),"No se pudo consultar el expediente."));var r=rs.one("parcela").orElse(null);if(r==null)return PersistenceResult.error("La parcela seleccionada no está disponible.");var plot=new CultivationModels.Plot(SqlValues.longValue(r,"parcela_id"),SqlValues.longValue(r,"predio_id"),SqlValues.string(r,"predioCodigo"),SqlValues.string(r,"predioNombre"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"),SqlValues.decimal(r,"area_ha"),SqlValues.bool(r,"estado"),SqlValues.longValue(r,"ubicacion_id"),SqlValues.string(r,"distrito_codigo"),SqlValues.longValue(r,"centro_poblado_id"),SqlValues.string(r,"referencia"),SqlValues.decimal(r,"latitud"),SqlValues.decimal(r,"longitud"),SqlValues.decimal(r,"altitud_m"));var crops=rs.rows("cultivos").stream().map(x->new CultivationModels.Crop(SqlValues.longValue(x,"parcela_cultivo_id"),SqlValues.longValue(x,"variedad_palta_id"),SqlValues.string(x,"variedadCodigo"),SqlValues.string(x,"variedad"),SqlValues.localDate(x,"fecha_inicio"),SqlValues.localDate(x,"fecha_fin"),SqlValues.string(x,"situacion_cultivo"),SqlValues.bool(x,"estado"))).toList();var censuses=rs.rows("censos").stream().map(this::census).toList();var evals=rs.rows("evaluaciones").stream().map(x->new CultivationModels.Evaluation(SqlValues.longValue(x,"evaluacion_agronomica_id"),SqlValues.longValue(x,"visita_tecnica_id"),SqlValues.longValue(x,"parcela_cultivo_id"),SqlValues.longValue(x,"tipo_evaluacion_id"),SqlValues.string(x,"tipoEvaluacion"),SqlValues.instant(x,"fecha_hora"),SqlValues.string(x,"resultado"),SqlValues.string(x,"observacion"),SqlValues.bool(x,"estado"))).toList();var files=rs.rows("archivos").stream().map(x->new CultivationModels.FileRef(SqlValues.longValue(x,"archivo_id"),SqlValues.string(x,"nombre_original"),SqlValues.string(x,"mime_type"),SqlValues.string(x,"secure_url"),SqlValues.instant(x,"fecha_carga"),SqlValues.string(x,"categoria"),SqlValues.string(x,"origen_captura"),SqlValues.longValue(x,"parcela_id"),SqlValues.longValue(x,"parcela_cultivo_id"),SqlValues.longValue(x,"censo_plantas_id"),SqlValues.longValue(x,"evaluacion_agronomica_id"))).toList();return PersistenceResult.ok(PaAdapterSupport.message(rs.raw(),"Expediente consultado correctamente."),new CultivationModels.Detail(plot,crops,censuses,evals,files));}
 public PersistenceResult<Long>createPlot(CreatePlot c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(createPlot,f.forWrite(i,m,c,Map.of("parcela",map("predioId",c.predioId(),"codigo",c.codigo(),"nombre",c.nombre(),"areaHa",c.areaHa()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nParcelaId"),"No se pudo registrar la parcela.");}
 public PersistenceResult<Void>updatePlot(UpdatePlot c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(updatePlot,f.forWrite(i,m,c,Map.of("parcela",map("parcelaId",c.parcelaId(),"predioId",c.predioId(),"codigo",c.codigo(),"nombre",c.nombre(),"areaHa",c.areaHa()))));return PaAdapterSupport.result(out,null,"No se pudo actualizar la parcela.");}
 public PersistenceResult<Long>createCrop(CreateCrop c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(createCrop,f.forWrite(i,m,c,Map.of("cultivo",map("parcelaId",c.parcelaId(),"variedadPaltaId",c.variedadPaltaId(),"fechaInicio",c.fechaInicio()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nParcelaCultivoId"),"No se pudo registrar el cultivo.");}
 public PersistenceResult<Void>updateCrop(UpdateCrop c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(updateCrop,f.forWrite(i,m,c,Map.of("cultivo",map("parcelaCultivoId",c.parcelaCultivoId(),"variedadPaltaId",c.variedadPaltaId(),"fechaInicio",c.fechaInicio()))));return PaAdapterSupport.result(out,null,"No se pudo actualizar el cultivo.");}
 public PersistenceResult<Void>finishCrop(FinishCrop c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(finishCrop,f.forWrite(i,m,c,Map.of("cultivo",map("parcelaCultivoId",c.parcelaCultivoId(),"fechaFin",c.fechaFin(),"motivo",c.motivo()))));return PaAdapterSupport.result(out,null,"No se pudo finalizar el cultivo.");}
 private CultivationModels.Summary summary(Map<String,Object>r){return new CultivationModels.Summary(SqlValues.longValue(r,"parcela_id"),SqlValues.longValue(r,"predio_id"),SqlValues.string(r,"predioCodigo"),SqlValues.string(r,"predioNombre"),SqlValues.string(r,"parcelaCodigo"),SqlValues.string(r,"parcelaNombre"),SqlValues.decimal(r,"area_ha"),SqlValues.longValue(r,"ubicacion_id"),SqlValues.bool(r,"parcelaEstado"),SqlValues.longValue(r,"parcela_cultivo_id"),SqlValues.longValue(r,"variedad_palta_id"),SqlValues.string(r,"variedad"),SqlValues.localDate(r,"fecha_inicio"),SqlValues.localDate(r,"fecha_fin"),SqlValues.string(r,"situacion_cultivo"),SqlValues.bool(r,"cultivoEstado"));}
 private CultivationModels.Census census(Map<String,Object>x){return new CultivationModels.Census(SqlValues.longValue(x,"censo_plantas_id"),SqlValues.longValue(x,"parcela_cultivo_id"),SqlValues.localDate(x,"fecha_censo"),SqlValues.intValue(x,"plantas_totales"),SqlValues.intValue(x,"plantas_productivas"),SqlValues.intValue(x,"plantas_no_productivas"),SqlValues.intValue(x,"plantas_nuevas"),SqlValues.intValue(x,"plantas_muertas"),SqlValues.intValue(x,"plantas_afectadas"),SqlValues.string(x,"observacion"),SqlValues.bool(x,"estado"));}
 private static Map<String,Object>map(Object...p){Map<String,Object>m=new LinkedHashMap<>();for(int x=0;x<p.length;x+=2)if(p[x+1]!=null)m.put((String)p[x],p[x+1]);return m;}}
